import { useEffect, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

function PatientDashboard() {

  const [myOP, setMyOP] = useState(null);

  const [form, setForm] = useState({
    patientName: "",
    doctor: "",
    department: "",
    date: ""
  });

  const [queueCount, setQueueCount] = useState(0);

  useEffect(() => {

    const fetchData = async () => {

      try {

        const res = await fetch(
          "http://localhost:5000/api/queue/all"
        );

        const data = await res.json();

        // ONLY MY OP
        const mine = data.find(
          q =>
            q.patientName === form.patientName
        );

        if (mine) {
          setMyOP(mine);
        }

        // QUEUE COUNT AFTER JOIN
        const total = data.filter(
          q => q.status === "InQueue"
        ).length;

        setQueueCount(total);

      } catch (err) {
        console.log(err);
      }

    };

    fetchData();

    socket.on(
      "queueUpdated",
      fetchData
    );

    return () => {
      socket.off("queueUpdated");
    };

  }, [form.patientName]);


  // BOOK OP
  const bookOP = async () => {

    try {

      const res = await fetch(
        "http://localhost:5000/api/queue/book",
        {
          method: "POST",

          headers: {
            "Content-Type":
              "application/json"
          },

          body: JSON.stringify(form)
        }
      );

      const data = await res.json();

      setMyOP(data);

      setForm({
        patientName: "",
        doctor: "",
        department: "",
        date: ""
      });

    } catch (err) {
      console.log(err);
    }

  };


  // JOIN QUEUE
  const joinQueue = async (id) => {

    try {

      await fetch(
        `http://localhost:5000/api/queue/join/${id}`,
        {
          method: "PUT"
        }
      );

    } catch (err) {
      console.log(err);
    }

  };


  return (

    <div style={{ padding: 20 }}>

      <h2>
        👤 Patient Dashboard
      </h2>

      {/* BOOK FORM */}

      {!myOP && (

        <div>

          <input
            placeholder="Patient Name"

            value={form.patientName}

            onChange={(e) =>
              setForm({
                ...form,
                patientName:
                  e.target.value
              })
            }
          />

          <br /><br />

          <input
            placeholder="Doctor"

            value={form.doctor}

            onChange={(e) =>
              setForm({
                ...form,
                doctor:
                  e.target.value
              })
            }
          />

          <br /><br />

          <input
            placeholder="Department"

            value={form.department}

            onChange={(e) =>
              setForm({
                ...form,
                department:
                  e.target.value
              })
            }
          />

          <br /><br />

          <input
            type="date"

            value={form.date}

            onChange={(e) =>
              setForm({
                ...form,
                date:
                  e.target.value
              })
            }
          />

          <br /><br />

          <button
            onClick={bookOP}
          >

            Book OP

          </button>

        </div>

      )}

      <hr />

      {/* ONLY MY OP */}

      {myOP && (

        <div
          style={{
            border:
              "1px solid black",
            padding: 15
          }}
        >

          <h3>
            My OP
          </h3>

          <p>
            Token:
            {myOP.tokenNumber}
          </p>

          <p>
            Doctor:
            {myOP.doctor}
          </p>

          <p>
            Status:
            {myOP.status}
          </p>

          {myOP.status ===
            "Confirmed" && (

              <button
                onClick={() =>
                  joinQueue(
                    myOP._id
                  )
                }
              >

                Join Queue

              </button>

            )}

          {myOP.status ===
            "InQueue" && (

              <div>

                <h4>

                  Queue Count:
                  {queueCount}

                </h4>

              </div>

            )}

        </div>

      )}

    </div>

  );

}

export default PatientDashboard;
